#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int* data;
    size_t size;
    size_t capacity;
} Vector;

void vector_init(Vector* v) {
    v->size = 0;
    v->capacity = 4;
    v->data = (int*)malloc(v->capacity * sizeof(int));
}

void vector_push(Vector* v, int val) {
    if (v->size == v->capacity) {
        v->capacity *= 2;
        v->data = (int*)realloc(v->data, v->capacity * sizeof(int));
    }
    v->data[v->size++] = val;
}

void vector_free(Vector* v) {
    free(v->data);
}

int main(void) {
    Vector v;
    vector_init(&v);
    vector_push(&v, 10);
    vector_push(&v, 20);
    printf("Vector size: %zu | capacity: %zu\n", v.size, v.capacity);
    vector_free(&v);
    return 0;
}

